import{_ as s,o as n,c as e,a4 as c}from"./chunks/framework.BaMAT_0D.js";const t="/my_note/20260602160047_1014_180.jpg",h=JSON.parse('{"title":"实验实战与课设 · Engineering Lab","description":"浙江大学计算机科学与技术专业实验报告、Vivado 工程、课程大作业与物理实验全归档","frontmatter":{"title":"实验实战与课设 · Engineering Lab","description":"浙江大学计算机科学与技术专业实验报告、Vivado 工程、课程大作业与物理实验全归档"},"headers":[],"relativePath":"Lab/index.md","filePath":"Lab/index.md","lastUpdated":1793361941000}'),i={name:"Lab/index.md"};function o(d,a,r,l,p,b){return n(),e("div",null,[...a[0]||(a[0]=[c('<h1 id="实验实战与课设-·-engineering-lab" tabindex="-1">实验实战与课设 · Engineering Lab <a class="header-anchor" href="#实验实战与课设-·-engineering-lab" aria-label="Permalink to &quot;实验实战与课设 · Engineering Lab&quot;">​</a></h1><div class="garden-badge">🧪 软硬件协同实战 · 从代码逻辑到硅片硬件与科学实验</div><p>这里系统归档了计科专业核心实验课、高阶算法课程大作业设计、硬件体系Vivado工程源码与普通物理学实验报告，供学术交流与课设参考。</p><hr><h2 id="⚡-核心硬件与体系实验-·-hardware-systems" tabindex="-1">⚡ 核心硬件与体系实验 · Hardware &amp; Systems <a class="header-anchor" href="#⚡-核心硬件与体系实验-·-hardware-systems" aria-label="Permalink to &quot;⚡ 核心硬件与体系实验 · Hardware &amp; Systems&quot;">​</a></h2><p>从门级组合时序逻辑到片上 SoC 计算机系统的全流程硬件设计实战：</p><div class="garden-bento-grid"><a href="./Digital-Logic-Design-Lab.html" class="bento-card"><div><div class="bento-card-top"><span class="bento-code-badge">DLD LAB</span><span class="bento-tag-badge lab">FPGA 实战</span></div><div class="bento-card-body"><div class="bento-icon-box">⚡</div><div class="bento-content"><span class="bento-title">数字逻辑设计实验</span><span class="bento-desc">Vivado 仿真与综合、FPGA 板卡管脚约束、状态机、13次系列实验报告与期末大作业完整工程</span></div></div></div><div class="bento-card-footer"><div class="bento-chips"><span class="bento-chip">Verilog HDL</span><span class="bento-chip">大作业完整工程</span></div><span class="bento-arrow">→</span></div></a><a href="./Computer-Organization-Lab.html" class="bento-card"><div><div class="bento-card-top"><span class="bento-code-badge">CO LAB</span><span class="bento-tag-badge lab">CPU 架构</span></div><div class="bento-card-body"><div class="bento-icon-box">🖥️</div><div class="bento-content"><span class="bento-title">计算机组成体系实验</span><span class="bento-desc">MIPS/RISC-V 单周期 CPU 设计、流水线冒险机制、IP2SOC 片上系统集成与软硬件协同验证</span></div></div></div><div class="bento-card-footer"><div class="bento-chips"><span class="bento-chip">IP2SOC 集成</span><span class="bento-chip">CPU 数据通路</span></div><span class="bento-arrow">→</span></div></a></div><hr><h2 id="🌲-核心算法与高阶课设-·-algorithm-course-projects" tabindex="-1">🌲 核心算法与高阶课设 · Algorithm Course Projects <a class="header-anchor" href="#🌲-核心算法与高阶课设-·-algorithm-course-projects" aria-label="Permalink to &quot;🌲 核心算法与高阶课设 · Algorithm Course Projects&quot;">​</a></h2><p>深入算法性能基准、复杂图网络优化与前沿启发式搜索的大作业设计报告：</p><div class="garden-bento-grid"><a href="./Fundamentals_of_Data_Structure/Project1_Search/project1.html" class="bento-card"><div><div class="bento-card-top"><span class="bento-code-badge">FDS P1</span><span class="bento-tag-badge core">性能评测</span></div><div class="bento-card-body"><div class="bento-icon-box">🔍</div><div class="bento-content"><span class="bento-title">FDS · 检索算法实测与性能分析</span><span class="bento-desc">顺序查找、二分查找及散列在不同规模数据集下的时间复杂度与实际执行时间精确基准对比</span></div></div></div><div class="bento-card-footer"><div class="bento-chips"><span class="bento-chip">Benchmarking</span><span class="bento-chip">经验复杂度</span></div><span class="bento-arrow">→</span></div></a><a href="./Fundamentals_of_Data_Structure/Project2_Polynomial/project2.html" class="bento-card"><div><div class="bento-card-top"><span class="bento-code-badge">FDS P2</span><span class="bento-tag-badge core">数据结构</span></div><div class="bento-card-body"><div class="bento-icon-box">📐</div><div class="bento-content"><span class="bento-title">FDS · 多项式代数与堆优化应用</span><span class="bento-desc">稀疏多项式符号运算、链表高效合并乘法与基于优先队列的运算优化算法设计</span></div></div></div><div class="bento-card-footer"><div class="bento-chips"><span class="bento-chip">优先队列</span><span class="bento-chip">多项式优化</span></div><span class="bento-arrow">→</span></div></a><a href="./Fundamentals_of_Data_Structure/Project3_Graph_Routing/report.html" class="bento-card"><div><div class="bento-card-top"><span class="bento-code-badge">FDS P3</span><span class="bento-tag-badge core">图论路由</span></div><div class="bento-card-body"><div class="bento-icon-box">🗺️</div><div class="bento-content"><span class="bento-title">FDS · 网格路由与图论最短路径</span><span class="bento-desc">大规模障碍物网格地图中的 Dijkstra / A* 寻路优化、路径平滑与内存占用性能剖析</span></div></div></div><div class="bento-card-footer"><div class="bento-chips"><span class="bento-chip">Dijkstra/A*</span><span class="bento-chip">网格寻路</span></div><span class="bento-arrow">→</span></div></a><a href="./Advanced_Data_Structure/Project2_ShortestPath/report.html" class="bento-card"><div><div class="bento-card-top"><span class="bento-code-badge">ADS P2</span><span class="bento-tag-badge core">斐波那契堆</span></div><div class="bento-card-body"><div class="bento-icon-box">🛣️</div><div class="bento-content"><span class="bento-title">ADS · 斐波那契堆与全美路网最短路径</span><span class="bento-desc">在数百万节点的真实 USA Road Networks 上深入对比二叉堆、4-ary 堆与斐波那契堆的理论与缓存瓶颈</span></div></div></div><div class="bento-card-footer"><div class="bento-chips"><span class="bento-chip">Fibonacci Heap</span><span class="bento-chip">Cache locality</span></div><span class="bento-arrow">→</span></div></a><a href="./Advanced_Data_Structure/Project1_SkipList/" class="bento-card"><div><div class="bento-card-top"><span class="bento-code-badge">ADS P1</span><span class="bento-tag-badge core">高阶结构</span></div><div class="bento-card-body"><div class="bento-icon-box">🎿</div><div class="bento-content"><span class="bento-title">ADS · SkipList 跳表与平衡树评测</span><span class="bento-desc">概率平衡跳跃表的数据结构实现、不同概率因子 p 对树高与命中率影响的基准仿真</span></div></div></div><div class="bento-card-footer"><div class="bento-chips"><span class="bento-chip">SkipList</span><span class="bento-chip">概率平衡</span></div><span class="bento-arrow">→</span></div></a><a href="./Advanced_Data_Structure/Project4_MaxClique/report.html" class="bento-card"><div><div class="bento-card-top"><span class="bento-code-badge">ADS P4</span><span class="bento-tag-badge core">NP问题</span></div><div class="bento-card-body"><div class="bento-icon-box">🎯</div><div class="bento-content"><span class="bento-title">ADS · 最大团问题分支限界启发式求解</span><span class="bento-desc">图的最大团（Max Clique）精确搜索、基于顶点着色上界剪枝的 Branch &amp; Bound 启发式加速</span></div></div></div><div class="bento-card-footer"><div class="bento-chips"><span class="bento-chip">Branch &amp; Bound</span><span class="bento-chip">图着色剪枝</span></div><span class="bento-arrow">→</span></div></a></div><hr><h2 id="🔬-普通物理学实验集-·-general-physics-lab" tabindex="-1">🔬 普通物理学实验集 · General Physics Lab <a class="header-anchor" href="#🔬-普通物理学实验集-·-general-physics-lab" aria-label="Permalink to &quot;🔬 普通物理学实验集 · General Physics Lab&quot;">​</a></h2><p>物理量精密测量、经典电磁力热仪器操作与前沿虚拟仿真实验：</p><div class="garden-bento-grid"><a href="./Physics-Lab.html" class="bento-card"><div><div class="bento-card-top"><span class="bento-code-badge">PHY LAB</span><span class="bento-tag-badge math">实验全景</span></div><div class="bento-card-body"><div class="bento-icon-box">🌌</div><div class="bento-content"><span class="bento-title">普通物理学实验总览与规范</span><span class="bento-desc">包含 14 项完整实验：碰撞、磁滞回线、万用表、双臂电桥、驻波、杨氏模量、示波器、霍尔效应、北斗卫星定位等</span></div></div></div><div class="bento-card-footer"><div class="bento-chips"><span class="bento-chip">14个系列报告</span><span class="bento-chip">全数据处理</span></div><span class="bento-arrow">→</span></div></a><a href="./Physics_Lab/II/Week_1-2-北斗导航定位模拟设计与应用/formal/formal.html" class="bento-card"><div><div class="bento-card-top"><span class="bento-code-badge">PHY-II</span><span class="bento-tag-badge lab">北斗导航</span></div><div class="bento-card-body"><div class="bento-icon-box">🛰️</div><div class="bento-content"><span class="bento-title">北斗导航定位模拟设计与应用</span><span class="bento-desc">伪距几何交会测量、星历解算、GDOP 精度衰减因子分析与工程抗干扰设计方案</span></div></div></div><div class="bento-card-footer"><div class="bento-chips"><span class="bento-chip">空间几何交会</span><span class="bento-chip">定位算法</span></div><span class="bento-arrow">→</span></div></a></div><hr><h2 id="实验避坑要诀-·-lab-tips-notes" tabindex="-1">实验避坑要诀 · Lab Tips &amp; Notes <a class="header-anchor" href="#实验避坑要诀-·-lab-tips-notes" aria-label="Permalink to &quot;实验避坑要诀 · Lab Tips &amp; Notes&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">⚠️ 实验代码与报告参考避坑提示</p><ul><li><strong>关于数逻实验(DLD Lab)</strong>: 本归档中数逻实验在 <code>Lab 9</code> 之后的实验部分存在部分时钟域和状态转移逻辑瑕疵，请各位同学参考时务必结合自身板卡逻辑独立推导验证；<strong>但期末大作业部分是经过全功能上板测试与答辩的完整可用版本</strong>，可安心参考思路！</li><li><strong>关于算法大作业(FDS/ADS Projects)</strong>: 复杂度分析不能停留在理论渐近符号，务必结合 <strong>Cache Locality（缓存局部性）</strong>、常数开销和分支预测代价；例如斐波那契堆理论复杂度极低，但指针跳转密集导致在普通路网规模下可能不如优化后的二叉堆。</li><li><strong>关于硬件调试</strong>: 硬件描述语言不同于顺序执行的高级语言，牢记&quot;电路并发思维&quot;，杜绝将非阻塞赋值(<code>&lt;=</code>)与阻塞赋值(<code>=</code>)混用的常见陷阱。</li></ul></div><hr><h2 id="助学智囊团-·-ai-research-assistants" tabindex="-1">助学智囊团 · AI Research Assistants <a class="header-anchor" href="#助学智囊团-·-ai-research-assistants" aria-label="Permalink to &quot;助学智囊团 · AI Research Assistants&quot;">​</a></h2><p>遇到硬件报错、Verilog 语法迷思或算法测试用例不通过时，可借助 AI 工具辅助排查：</p><div class="ai-assistant-grid"><a href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer" class="ai-assistant-card"><div class="ai-card-icon">🤖</div><div class="ai-card-info"><span class="ai-card-name">ChatGPT</span><span class="ai-card-desc">综合能力强，适合 Verilog 语法纠错与算法测试样例构造</span></div></a><a href="https://claude.ai/" target="_blank" rel="noopener noreferrer" class="ai-assistant-card"><div class="ai-card-icon">🧠</div><div class="ai-card-info"><span class="ai-card-name">Claude</span><span class="ai-card-desc">严谨细致，擅长分析大作业实验报告架构与算法正确性证明</span></div></a><a href="https://deepseek.com/" target="_blank" rel="noopener noreferrer" class="ai-assistant-card"><div class="ai-card-info">⚡</div><div class="ai-card-info"><span class="ai-card-name">DeepSeek</span><span class="ai-card-desc">国产推理利器，擅长算法复杂度瓶颈推导与 C++ 性能调优</span></div></a><a href="https://gemini.google.com/" target="_blank" rel="noopener noreferrer" class="ai-assistant-card"><div class="ai-card-info">💎</div><div class="ai-card-info"><span class="ai-card-name">Gemini</span><span class="ai-card-desc">多模态能力出众，可上传电路原理图与物理实验波形截图辅助分析</span></div></a><a href="https://kimi.moonshot.cn/" target="_blank" rel="noopener noreferrer" class="ai-assistant-card"><div class="ai-card-info">🌙</div><div class="ai-card-info"><span class="ai-card-name">Kimi</span><span class="ai-card-desc">长文本阅读利器，擅长速读芯片手册 Datasheet 与实验指导书</span></div></a><a href="https://grok.com/" target="_blank" rel="noopener noreferrer" class="ai-assistant-card"><div class="ai-card-info">🚀</div><div class="ai-card-info"><span class="ai-card-name">Grok</span><span class="ai-card-desc">风格直接幽默，快速探讨前沿硬件架构与极客技巧</span></div></a></div><div class="garden-photo-frame"><img src="'+t+'" alt="Lab Focus"><div class="garden-photo-caption">Practice Makes Perfect · 软硬协同，行而不辍，履践致远</div></div>',23)])])}const g=s(i,[["render",o]]);export{h as __pageData,g as default};
